const payload = $input.first().json;
const data = payload.data || payload;

const statusEmoji = {
  'CONFIRMED': '✅',
  'PROCESSING': '⚙️',
  'RIDER_ASSIGNED': '🏍️',
  'RIDER_AT_PHARMACY': '💊',
  'RIDER_PICKED_UP': '📦',
  'OUT_FOR_DELIVERY': '🚴',
  'DELIVERED': '🎉',
  'FAILED': '❌',
  'CANCELLED': '🚫',
};

const emoji = statusEmoji[data.newStatus] || '📋';

return [{
  json: {
    subject: `${emoji} Order ${data.trackingNumber} → ${data.newStatus}`,
    body: `Order status update for MediFind.\n\n` +
          `Tracking: ${data.trackingNumber}\n` +
          `Status: ${data.previousStatus} → ${data.newStatus}\n` +
          `Customer: ${data.userName || 'N/A'} (${data.userEmail || 'N/A'})\n` +
          `Rider: ${data.riderName || 'Not assigned'} (${data.riderEmail || 'N/A'})\n` +
          `Pharmacy: ${data.pharmacyName || 'N/A'}\n` +
          `Delivery To: ${data.deliveryAddress || 'N/A'}\n\n` +
          `Updated at: ${payload.timestamp}`,
    ...data,
    isDelivered: data.newStatus === 'DELIVERED',
    isAssigned: data.newStatus === 'RIDER_ASSIGNED',
  }
}];
